/* send_nodal_api.c (linear send) - the reissue card's SEND half as a linear block + the zener pair WITH its midpoint,
 * behind the calls of send_nodal_api.h (the plugin takes it by pointing ULTRA_SEND_DIR here).
 *   linear: R12, R11, R4, C8, R8 from w2 to node c (one state, v_C8), generated by gen_linsend_c.py (linsend_circuit.h) and
 *     discretised at the engine rate by Van Loan's exponential (w2 with a first-order hold, the port current into c held
 *     at its new value over the step, as linret);
 *   the pair: D1 anode c, cathode m; D2 anode VREF, cathode m (12 V zeners, nlcore nl_dev_zener.h's law: the static
 *     I-V and the forward diode's depletion charge, both tabulated at instantiate). A STATIC pair (no midpoint state) is
 *     only -25..-30 dB from the full circuit even at 768 kHz: the floating midpoint's charge is memory.
 *     Unknowns per sample: v_c and v_m, a 2x2 Newton (warm start); the junction charge by the trapezoid
 *     (LS_CHARGE_TR, the default) or backward Euler.
 * Input w2 against VREF, output c against VREF (IC1a's input). No allocation after cs_send_new. */
#include <stdlib.h>
#include "linsend_circuit.h"
#include "../ret/linret_circuit.h"     /* the zener law's constants (LR_VT, LR_Z_*), generated from the same lib */
#include "../lr_common.h"
#include "send_nodal_api.h"

#define LS_V0 (-24.0)       /* the junction table: v in [LS_V0, LS_V1], cubic Hermite on (i, g) and on (q, c) */
#define LS_V1 3.0
#define LS_INV 200.0        /* 5 mV */
#define LS_NT 5401
#define LS_NEWTON_MAX 40
#ifndef LS_PORT_FOH
#define LS_PORT_FOH 0       /* 1: the port current into c with a first-order hold (a ramp) instead of held */
#endif
#ifndef LS_CHARGE_TR
#define LS_CHARGE_TR 1      /* the junction charge by the trapezoid (0: backward Euler, 7-16 dB worse in the audio band) */
#endif
#ifndef LS_LIM
#define LS_LIM 0.5          /* volts: the largest junction step per Newton iteration */
#endif
#ifndef LS_GUESS
#define LS_GUESS 11.0       /* volts: beyond this |v0| Newton starts from the static pair's solution (the clamp) */
#endif
#ifndef LS_TOL
#define LS_TOL 3e-3         /* volts: Newton's last step. Against a 1e-7 stop the error peaks below -85 dB, 40+ dB
                             * under the send's model error against the circuit; 1e-2 lets the peak reach -64 dB */
#endif


typedef struct {
    double Phi, G0w, G1w, G0z, G1z, C, Dw, Dz, R11, T;
    double ti[LS_NT], tg[LS_NT], tq[LS_NT], tc[LS_NT];
    double sv0[LR_NZ], sm[LR_NZ];                        /* the STATIC pair at c: open-circuit v0 -> its midpoint v_m (Newton's start in the clamp) */
    LrZener zs;                                          /* ... and its current (lr_common's table, R11 = this port's) */
    double x, wprev, izprev, vc, vm, vc1, vm1, qa_prev, qb_prev, ca_prev, cb_prev;   /* c?_prev: the junctions' charge currents (trapezoid) */
    long nonconv;
} LinSend;

/* a junction from the table: current i and slope g, charge q and capacitance c, at port voltage v */
static inline void ls_junction(const LinSend* s, double v, double* i, double* g, double* q, double* c)
{
    double a = (v - LS_V0) * LS_INV;
    if (a < 0.0 || a >= LS_NT - 1) {   /* outside: the tangent at the edge (no circuit here gets there) */
        const int k = a < 0.0 ? 0 : LS_NT - 1; const double dv = v - (LS_V0 + k / LS_INV);
        *i = s->ti[k] + s->tg[k] * dv; *g = s->tg[k]; *q = s->tq[k] + s->tc[k] * dv; *c = s->tc[k];
        return;
    }
    const int k = (int)a; const double t = a - k, h = 1.0 / LS_INV;
    const double t2 = t * t, t3 = t2 * t;
    const double h00 = 2 * t3 - 3 * t2 + 1, h10 = t3 - 2 * t2 + t, h01 = -2 * t3 + 3 * t2, h11 = t3 - t2;
    const double d00 = (6 * t2 - 6 * t) * LS_INV, d10 = (3 * t2 - 4 * t + 1), d01 = (-6 * t2 + 6 * t) * LS_INV, d11 = (3 * t2 - 2 * t);
    *i = h00 * s->ti[k] + h10 * h * s->tg[k] + h01 * s->ti[k + 1] + h11 * h * s->tg[k + 1];
    *g = d00 * s->ti[k] + d10 * s->tg[k] + d01 * s->ti[k + 1] + d11 * s->tg[k + 1];
    *q = h00 * s->tq[k] + h10 * h * s->tc[k] + h01 * s->tq[k + 1] + h11 * h * s->tc[k + 1];
    *c = d00 * s->tq[k] + d10 * s->tc[k] + d01 * s->tq[k + 1] + d11 * s->tc[k + 1];
}

void* cs_send_new(double fs, int level)
{
    LinSend* s = calloc(1, sizeof *s);
    if (!s) return NULL;
    const double (*A)[1] = level ? LS_A1 : LS_A0, (*B)[2] = level ? LS_B1 : LS_B0;
    const double (*C)[1] = level ? LS_C1 : LS_C0, (*D)[2] = level ? LS_D1 : LS_D0;
    const int n = LS_NX, nu = LS_NU, N = n + 2 * nu;
    s->T = 1.0 / fs;
    double Z[144] = { 0 }, E[144];
    Z[0] = A[0][0] * s->T;
    for (int j = 0; j < nu; j++) Z[n + j] = B[0][j] * s->T;
    for (int j = 0; j < nu; j++) Z[(n + j) * N + n + nu + j] = 1.0;
    expm(N, Z, E);
    s->Phi = E[0];
    s->G1w = E[n + nu]; s->G0w = E[n] - E[n + nu];   /* w2: first-order hold */
#if LS_PORT_FOH
    s->G1z = E[n + nu + 1]; s->G0z = E[n + 1] - E[n + nu + 1];   /* the port: a ramp */
#else
    s->G1z = E[n + 1]; s->G0z = 0.0;                  /* the port: held */
#endif
    s->C = C[0][0]; s->Dw = D[0][0]; s->Dz = D[0][1];
    s->R11 = s->C * s->G1z + s->Dz;
    if (!(s->R11 > 0.0)) { free(s); return NULL; }
    NlZener z; zener_law(&z);
    z.cjo = LR_Z_F_CJO; z.vj = LR_Z_F_VJ; z.m = LR_Z_F_M; z.fc = LR_Z_F_FC; nl_zener_init(&z);   /* DFOR's depletion charge */
    for (int k = 0; k < LS_NT; k++) {
        const double v = LS_V0 + k / LS_INV;
        nl_zener_iv(&z, v, &s->ti[k], &s->tg[k]);
        nl_zener_qc(&z, v, &s->tq[k], &s->tc[k]);
    }
    /* the static pair (no charge) at this port: Newton's start in the clamp, where the linear predictor starts below the knee
     * and Newton would walk down the exponential one VT per iteration */
    s->zs.R11 = s->R11;
    zener_pair_table(&s->zs);
    {   const double I0 = 1e-13, imax = 0.7, amax = asinh(imax / I0); double v4 = 0.0;
        for (int k = 0; k < LR_NZ; k++) {
            const double I = I0 * sinh(amax * (2.0 * k / (LR_NZ - 1) - 1.0));
            v4 = zener_inv(&z, -I, v4); s->sm[k] = -v4; s->sv0[k] = s->zs.zv0[k];
        }
    }
    cs_send_reset(s);
    return s;
}

int cs_send_reset(void* sv)
{
    LinSend* s = sv;
    s->x = 0.0; s->wprev = 0.0; s->izprev = 0.0; s->vc = s->vm = s->vc1 = s->vm1 = 0.0;   /* the DC point with w2 at VREF: c and m at VREF */
    s->ca_prev = s->cb_prev = 0.0;
    double i, g, c; ls_junction(s, 0.0, &i, &g, &s->qa_prev, &c); s->qb_prev = s->qa_prev;
    s->nonconv = 0;
    return 0;
}

double cs_send_tick(void* sv, double w2)
{
    LinSend* s = sv;
    const double xp = s->Phi * s->x + s->G0w * s->wprev + s->G1w * w2 + s->G0z * s->izprev;
    const double v0 = s->C * xp + s->Dw * w2;          /* node c with no pair current */
#if LS_CHARGE_TR
    const double iT = 2.0 / s->T, ha = s->ca_prev, hb = s->cb_prev;   /* i = 2 (q - q_prev) / T - i_prev */
#else
    const double iT = 1.0 / s->T, ha = 0.0, hb = 0.0;
#endif
    const double R = s->R11;
    /* unknowns (vc, vm). F1: node c = its open-circuit value v0 minus R x the current it sources into D1; F2: the
     * midpoint's KCL. a11..a22 = d(F1, F2) / d(vc, vm). The start: the last two samples' line (a predictor) */
    double vc = 2.0 * s->vc - s->vc1, vm = 2.0 * s->vm - s->vm1, j1 = 0.0,
           qa = 0.0, qb = 0.0, cha = 0.0, chb = 0.0;
    if (fabs(v0) > LS_GUESS) {   /* the clamp: the static pair's solution */
        int lo = 0, hi = LR_NZ - 1;
        if (v0 <= s->sv0[0]) hi = 1; else if (v0 >= s->sv0[LR_NZ - 1]) lo = LR_NZ - 2;
        else while (hi - lo > 1) { const int mm = (lo + hi) >> 1; if (s->sv0[mm] > v0) hi = mm; else lo = mm; }
        const double t = (v0 - s->sv0[lo]) / (s->sv0[lo + 1] - s->sv0[lo]);
        const double I = s->zs.zi[lo] + t * (s->zs.zi[lo + 1] - s->zs.zi[lo]);
        vc = v0 - R * I; vm = s->sm[lo] + t * (s->sm[lo + 1] - s->sm[lo]);
    }
    int it = 0;
    for (; it < LS_NEWTON_MAX; it++) {
        double ia, ga, ca, ib, gb, cb;
        ls_junction(s, vc - vm, &ia, &ga, &qa, &ca);             /* D1: c -> m */
        ls_junction(s, -vm, &ib, &gb, &qb, &cb);                 /* D2: VREF -> m */
        cha = (qa - s->qa_prev) * iT - ha; chb = (qb - s->qb_prev) * iT - hb;   /* the charge currents */
        j1 = ia + cha;                                  /* D1's total current, c into m */
        const double j2 = ib + chb;                     /* D2's, VREF into m */
        const double G1 = ga + ca * iT, G2 = gb + cb * iT;
        const double F1 = vc - v0 + R * j1, F2 = j1 + j2;
        const double a11 = 1.0 + R * G1, a12 = -R * G1, a21 = G1, a22 = -G1 - G2;
        const double det = a11 * a22 - a12 * a21;
        double dc = (F1 * a22 - a12 * F2) / det, dm = (a11 * F2 - a21 * F1) / det;
        /* a junction step limited to 0.5 V (the table's tangents outside keep it finite; this keeps Newton on the knee) */
        const double lim = LS_LIM, big = fabs(dc) > fabs(dm) ? fabs(dc) : fabs(dm);
        if (big > lim) { dc *= lim / big; dm *= lim / big; }
        vc -= dc; vm -= dm;
        /* the values at the new point by the same linearisation (their error is second order in the step) */
        const double da = -(dc - dm), db = dm;
        j1 += G1 * da; qa += ca * da; qb += cb * db; cha += ca * iT * da; chb += cb * iT * db;
        if (big < LS_TOL) break;
    }
    if (it == LS_NEWTON_MAX) s->nonconv++;
    s->ca_prev = cha; s->cb_prev = chb;
    s->qa_prev = qa; s->qb_prev = qb; s->vc1 = s->vc; s->vm1 = s->vm; s->vc = vc; s->vm = vm;
    const double iz = -j1;                              /* the port current INTO c */
    s->x = xp + s->G1z * iz;
    s->wprev = w2; s->izprev = iz;
    return s->C * s->x + s->Dw * w2 + s->Dz * iz;
}

long cs_send_nonconv(void* s) { return ((LinSend*)s)->nonconv; }
